package com.ds.goroute.controller;
import com.ds.goroute.dto.BaseResponse;import com.ds.goroute.dto.request.*;import com.ds.goroute.dto.response.*;import com.ds.goroute.service.ActivityCommerceService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.authentication.AuthenticationCredentialsNotFoundException;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;import java.util.*;
@RestController @RequestMapping("/v1/api/partner/activities") @RequiredArgsConstructor
public class PartnerActivityCommerceController {private final ActivityCommerceService s;@GetMapping public ResponseEntity<BaseResponse<List<MarketplaceActivityResponse>>> list(Authentication a,@RequestParam UUID organizationId){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerList(user(a),organizationId)));}@PostMapping public ResponseEntity<BaseResponse<MarketplaceActivityResponse>> create(Authentication a,@Valid @RequestBody UpsertMarketplaceActivityRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(BaseResponse.ofSucceeded(s.partnerCreate(user(a),r)));}@PutMapping("/{id}")public ResponseEntity<BaseResponse<MarketplaceActivityResponse>> update(Authentication a,@PathVariable UUID id,@Valid @RequestBody UpsertMarketplaceActivityRequest r){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerUpdate(user(a),id,r)));}@GetMapping("/{id}/packages")public ResponseEntity<BaseResponse<List<ActivityPackageResponse>>> packages(Authentication a,@PathVariable UUID id){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerPackages(user(a),id)));}@PostMapping("/{id}/packages")public ResponseEntity<BaseResponse<ActivityPackageResponse>> createPackage(Authentication a,@PathVariable UUID id,@Valid @RequestBody UpsertActivityPackageRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(BaseResponse.ofSucceeded(s.partnerCreatePackage(user(a),id,r)));}@PutMapping("/packages/{id}")public ResponseEntity<BaseResponse<ActivityPackageResponse>> updatePackage(Authentication a,@PathVariable UUID id,@Valid @RequestBody UpsertActivityPackageRequest r){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerUpdatePackage(user(a),id,r)));}@GetMapping("/packages/{id}/slots")public ResponseEntity<BaseResponse<List<ActivitySlotResponse>>> slots(Authentication a,@PathVariable UUID id,@RequestParam(required=false)LocalDateTime from){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerSlots(user(a),id,from)));}@PostMapping("/packages/{id}/slots")public ResponseEntity<BaseResponse<ActivitySlotResponse>> createSlot(Authentication a,@PathVariable UUID id,@Valid @RequestBody UpsertActivitySlotRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(BaseResponse.ofSucceeded(s.partnerCreateSlot(user(a),id,r)));}@PutMapping("/slots/{id}")public ResponseEntity<BaseResponse<ActivitySlotResponse>> updateSlot(Authentication a,@PathVariable UUID id,@Valid @RequestBody UpsertActivitySlotRequest r){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerUpdateSlot(user(a),id,r)));}@GetMapping("/orders")public ResponseEntity<BaseResponse<List<ActivityOrderResponse>>> orders(Authentication a,@RequestParam UUID organizationId,@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerOrders(user(a),organizationId,status,page,size)));}@GetMapping("/orders/{id}")public ResponseEntity<BaseResponse<ActivityOrderResponse>> order(Authentication a,@PathVariable UUID id){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerOrder(user(a),id)));}@PatchMapping("/orders/{id}/status")public ResponseEntity<BaseResponse<ActivityOrderResponse>> status(Authentication a,@PathVariable UUID id,@Valid @RequestBody UpdateActivityOrderStatusRequest r){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerOrderStatus(user(a),id,r)));}private UUID user(Authentication a){if(a==null||a.getPrincipal()==null)throw new AuthenticationCredentialsNotFoundException("Authentication required");Object p=a.getPrincipal();return p instanceof UUID id?id:UUID.fromString(p.toString());}}
